<?php
declare(strict_types=1);
session_start();

/**
 * 정산자동화 대시보드 (서버 버전).
 *
 * build_dashboard.py 가 이 파일 뒤에 대시보드 HTML을 붙여 outputs/deploy/index.php 를 만듭니다.
 * 이 파일을 직접 고치지 말고 work/server/index.head.php 를 고친 뒤 빌드를 다시 돌리세요.
 *
 * 하는 일:
 *   1. db.config.php 의 비밀번호로 로그인 확인 — 통과하지 못하면 HTML을 아예 내보내지 않습니다.
 *   2. MariaDB에 저장된 화면 상태를 읽어 EAP_SERVER_STATE 로 페이지에 심어 줍니다.
 *   3. 이후 화면에서 바뀐 내용은 api.php 가 같은 테이블에 저장합니다.
 *
 * 상담사 이름·계좌번호·정산금액이 보이는 페이지이니 반드시 HTTPS 주소로만 접속하세요.
 */

require_once __DIR__ . '/lib.php';

$config = eap_load_config();
if (!$config) {
    http_response_code(500);
    die('db.config.php 를 찾지 못했습니다. index.php 와 같은 폴더(또는 상위 폴더)에 올려 주세요.');
}

if (isset($_GET['logout'])) {
    $_SESSION = [];
    session_destroy();
    header('Location: index.php');
    exit;
}

$loginError = '';
$expectedPassword = eap_login_password($config);
if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['password'])) {
    if ($expectedPassword === '') {
        $loginError = 'db.config.php 에 settlement_password 가 아직 설정되지 않았습니다.';
    } elseif (hash_equals($expectedPassword, (string) $_POST['password'])) {
        session_regenerate_id(true);
        $_SESSION[EAP_SESSION_KEY] = true;
    } else {
        $loginError = '비밀번호가 올바르지 않습니다.';
    }
}

if (!eap_is_authed()) {
    ?>
<!doctype html>
<html lang="ko">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>정산자동화 대시보드 로그인</title>
<style>
  body { font-family:'Pretendard','Noto Sans KR','Malgun Gothic',sans-serif; max-width:360px; margin:120px auto; padding:0 20px; color:#2E2F31; }
  h2 { font-size:1.1rem; margin-bottom:14px; }
  input { width:100%; padding:10px; margin:8px 0; box-sizing:border-box; border:1px solid #DEDFE1; border-radius:6px; font-size:16px; }
  button { width:100%; padding:10px; background:#14B8A6; color:#fff; border:none; border-radius:6px; cursor:pointer; font-size:.95rem; font-weight:700; }
  .err { color:#A32D2D; font-size:.82rem; }
</style>
</head>
<body>
  <h2>정산자동화 대시보드</h2>
  <?php if ($loginError !== ''): ?><p class="err"><?= htmlspecialchars($loginError, ENT_QUOTES, 'UTF-8') ?></p><?php endif; ?>
  <form method="post">
    <input type="password" name="password" placeholder="비밀번호" autofocus>
    <button type="submit">로그인</button>
  </form>
</body>
</html>
    <?php
    exit;
}

$eapState = [];
$eapLoadError = '';
try {
    $pdo = eap_connect($config);
    eap_ensure_table($pdo);
    $eapState = eap_load_state($pdo);
} catch (PDOException $e) {
    // DB가 잠깐 안 되더라도 화면 자체는 뜨게 두고, 저장 시도할 때 api.php 가 오류를 알려준다.
    $eapLoadError = 'DB 연결에 실패했습니다. 저장한 내용이 보이지 않을 수 있습니다.';
}

$eapBootstrap = 'window.EAP_SERVER_MODE = true; window.EAP_SERVER_STATE = '
    . json_encode((object) $eapState, JSON_UNESCAPED_UNICODE | JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT)
    . ';';
if ($eapLoadError !== '') {
    $eapBootstrap .= ' window.EAP_SERVER_LOAD_ERROR = '
        . json_encode($eapLoadError, JSON_UNESCAPED_UNICODE | JSON_HEX_TAG) . ';';
}
?>
