                  <input id="centerSearch" placeholder="센터명/ID/지역 검색" /><span class="count-pill" id="centerCount"></span>
                  <label class="upload-btn">상담센터 엑셀 올리기<input type="file" id="centerUpload" accept=".xlsx,.xls" hidden /></label>
