                  <label class="upload-btn">상담사 엑셀 올리기<input type="file" id="counselorUpload" accept=".xlsx,.xls" hidden /></label>
                  <span class="upload-status" id="counselorUploadStatus"></span>
                </div>
              </div>
              <div class="table-wrap"><table id="counselorTable"></table></div>
            </div>
