    // ---------- shared helpers ----------
    const money = v => new Intl.NumberFormat("ko-KR").format(Math.round(Number(v || 0))) + "원";
    const count = v => new Intl.NumberFormat("ko-KR").format(Number(v || 0));
    function escapeHtml(v) {
      return String(v === undefined || v === null ? "" : v).replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
    }
    function groupBy(rows, fn) {
      const map = new Map();
      rows.forEach(r => { const k = fn(r); if (!map.has(k)) map.set(k, []); map.get(k).push(r); });
      return [...map.entries()];
    }
    function sum(rows, fn) { return rows.reduce((a, r) => a + Number(fn(r) || 0), 0); }
    function textMatch(row, q) { return !q || JSON.stringify(row).toLowerCase().includes(q.toLowerCase()); }
    function emptyRow(colspan) { return `<tbody><tr><td colspan="${colspan}" class="empty">표시할 데이터가 없습니다.</td></tr></tbody>`; }
    function downloadCsv(filename, headers, rows) {
      const esc = v => { const s = String(v === undefined || v === null ? "" : v); return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; };
      const csv = [headers.map(esc).join(","), ...rows.map(r => r.map(esc).join(","))].join("\r\n");
      const blob = new Blob(["﻿" + csv], { type: "text/csv;charset=utf-8;" });
      const a = document.createElement("a");
      a.href = URL.createObjectURL(blob);
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      a.remove();
    }
    function downloadXlsx(filename, headers, rows, sheetName) {
      const ws = XLSX.utils.aoa_to_sheet([headers, ...rows]);
      ws["!cols"] = headers.map((h, i) => {
        let width = String(h).length;
        rows.forEach(r => { width = Math.max(width, String(r[i] === undefined || r[i] === null ? "" : r[i]).length); });
        return { wch: Math.min(40, Math.max(10, width + 2)) };
      });
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, sheetName || "Sheet1");
      XLSX.writeFile(wb, filename);
    }

    // ---------- sidebar navigation ----------
