      cost: { title: "센터별 상담사 비용", desc: "이 화면에서 직접 입력합니다. 입력 내용은 이 브라우저에 자동 저장됩니다." },
      grade: { title: "센터 상담사 등급", desc: "이 화면에서 직접 입력하거나 CSV로 올릴 수 있습니다. 입력 내용은 이 브라우저에 자동 저장됩니다." },
      settlement: { title: "월별 정산 보고서", desc: "정산월을 선택하면 구글시트 데이터를 가져와 월별 정산 내역을 정리합니다." },
