    // ---------- read-only board tables ----------
    function renderBoard(tableId, data, query) {
      const q = (query || "").trim().toLowerCase();
      const rows = data.rows.filter(r => !q || r.some(v => String(v).toLowerCase().includes(q)));
      document.getElementById(tableId).innerHTML =
        `<thead><tr>${data.headers.map(h => `<th>${escapeHtml(h)}</th>`).join("")}</tr></thead>` +
        (rows.length
          ? `<tbody>${rows.map(r => `<tr>${r.map(v => `<td>${escapeHtml(v)}</td>`).join("")}</tr>`).join("")}</tbody>`
          : emptyRow(data.headers.length));
      return rows.length;
    }
    function wireBoard(searchId, tableId, countId, initialData) {
      let data = initialData;
      const update = () => {
        const n = renderBoard(tableId, data, document.getElementById(searchId).value);
        document.getElementById(countId).textContent = `${count(n)} / ${count(data.rows.length)}건`;
      };
      document.getElementById(searchId).addEventListener("input", update);
      update();
      return { setData: newData => { data = newData; update(); } };
    }
    const centerBoard = wireBoard("centerSearch", "centerTable", "centerCount", seed.centers);
    const counselorBoard = wireBoard("counselorSearch", "counselorTable", "counselorCount", seed.counselors);
    const expertBoard = wireBoard("expertSearch", "expertTable", "expertCount", seed.experts);

    // ---------- month-filterable boards (대면/비대면 상담 기록) ----------
    function monthsIn(data, dateColIndex) {
      const set = new Set();
      data.rows.forEach(r => {
        const v = String(r[dateColIndex] || "").slice(0, 7);
        if (/^\d{4}-\d{2}$/.test(v)) set.add(v);
      });
      return [...set].sort().reverse();
    }
    function wireMonthlyBoard(searchId, monthSelectId, tableId, countId, initialData, dateColIndex) {
      let data = initialData;
      const monthSel = document.getElementById(monthSelectId);
      function refreshMonths() {
        const months = monthsIn(data, dateColIndex);
        monthSel.innerHTML = `<option value="">전체 기간</option>` + months.map(m => `<option value="${m}">${m}</option>`).join("");
        // 데이터가 있으면 실제 이번 달을 기본값으로 열고, 없으면 데이터가 있는 가장 최근 달로 대체한다.
        const now = new Date();
        const currentMonth = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}`;
        if (months.includes(currentMonth)) monthSel.value = currentMonth;
        else if (months.length) monthSel.value = months[0];
      }
      function filteredData() {
        const m = monthSel.value;
        if (!m) return data;
        return { headers: data.headers, rows: data.rows.filter(r => String(r[dateColIndex] || "").slice(0, 7) === m) };
      }
      const update = () => {
        const fd = filteredData();
        const n = renderBoard(tableId, fd, document.getElementById(searchId).value);
        document.getElementById(countId).textContent = `${count(n)} / ${count(fd.rows.length)}건 (전체 ${count(data.rows.length)}건)`;
      };
      monthSel.addEventListener("change", update);
      document.getElementById(searchId).addEventListener("input", update);
      refreshMonths();
      update();
      return { setData: newData => { data = newData; refreshMonths(); update(); } };
    }
    const faceBoard = wireMonthlyBoard("faceDataSearch", "faceDataMonth", "faceDataTable", "faceDataCount", seed.faceData, seed.faceDataMonthCol);
    const remoteBoard = wireMonthlyBoard("remoteDataSearch", "remoteDataMonth", "remoteDataTable", "remoteDataCount", seed.remoteData, seed.remoteDataMonthCol);

    // ---------- editable grids (cost / grade) ----------
    function makeEditableGrid(opts) {
      const storageKey = opts.storageKey;
      const headers = opts.seed.headers;
      let rows = [];
      try {
        const stored = JSON.parse(store.getItem(storageKey) || "null");
        rows = Array.isArray(stored) ? stored : opts.seed.rows.map(r => r.slice());
      } catch (e) {
        rows = opts.seed.rows.map(r => r.slice());
      }
      let saveTimer = null;
      function persist() {
        store.setItem(storageKey, JSON.stringify(rows));
        const status = document.getElementById(opts.statusId);
        const now = new Date();
        const hh = String(now.getHours()).padStart(2, "0");
        const mm = String(now.getMinutes()).padStart(2, "0");
        const ss = String(now.getSeconds()).padStart(2, "0");
        status.textContent = `자동 저장됨 ${hh}:${mm}:${ss}`;
        if (opts.onChange) opts.onChange(rows);
      }
      function scheduleSave() {
        clearTimeout(saveTimer);
        saveTimer = setTimeout(persist, 300);
      }
      function render() {
        const q = document.getElementById(opts.searchId).value.trim().toLowerCase();
        const table = document.getElementById(opts.tableId);
        const visibleIndexes = rows
          .map((r, i) => i)
          .filter(i => !q || rows[i].some(v => String(v).toLowerCase().includes(q)));
        table.innerHTML = `<thead><tr>${headers.map(h => `<th>${escapeHtml(h)}</th>`).join("")}<th style="width:70px;">삭제</th></tr></thead>` +
          (visibleIndexes.length
            ? `<tbody>${visibleIndexes.map(i => `<tr data-row="${i}">${headers.map((h, c) => `<td><input data-row="${i}" data-col="${c}" value="${escapeHtml(rows[i][c])}" /></td>`).join("")}<td class="del-cell"><button class="row-del-btn danger" data-del="${i}">삭제</button></td></tr>`).join("")}</tbody>`
            : emptyRow(headers.length + 1));
        table.querySelectorAll("input").forEach(input => {
          input.addEventListener("input", e => {
            const r = Number(e.target.dataset.row);
            const c = Number(e.target.dataset.col);
            rows[r][c] = e.target.value;
            scheduleSave();
          });
        });
        table.querySelectorAll("[data-del]").forEach(btn => {
          btn.addEventListener("click", () => {
            const idx = Number(btn.dataset.del);
            rows.splice(idx, 1);
            persist();
            render();
          });
        });
      }
      document.getElementById(opts.addId).addEventListener("click", () => {
        rows.push(headers.map(() => ""));
        persist();
        render();
      });
      document.getElementById(opts.exportId).addEventListener("click", () => {
        downloadCsv(opts.exportName, headers, rows);
      });
      document.getElementById(opts.resetId).addEventListener("click", () => {
        if (!confirm("이 화면에서 입력/수정한 내용이 모두 사라지고 엑셀 원본 값으로 되돌아갑니다. 계속할까요?")) return;
        rows = opts.seed.rows.map(r => r.slice());
        persist();
        render();
      });
      document.getElementById(opts.searchId).addEventListener("input", render);
      render();
      function setRows(newRows) {
        rows = newRows.map(r => r.slice());
        persist();
        render();
      }
      return { getRows: () => rows, setRows };
    }

    const costGrid = makeEditableGrid({
      storageKey: "eap-cost-table-v1",
