    // ---------- overview stats ----------
    function renderOverviewStats() {
      const overviewMonth = defaultRelevantMonth();
      const faceMonthCount = seed.faceData.rows.filter(r => String(r[seed.faceDataMonthCol] || "").slice(0, 7) === overviewMonth).length;
      const remoteMonthCount = seed.remoteData.rows.filter(r => String(r[seed.remoteDataMonthCol] || "").slice(0, 7) === overviewMonth).length;
      document.getElementById("overviewStats").innerHTML = [
        ["상담센터 수", count(seed.centers.rows.length) + "개"],
        ["상담센터 상담사 수", count(seed.counselors.rows.length) + "명"],
        ["전문가 수", count(seed.experts.rows.length) + "명"],
        [`대면 상담 데이터 (${overviewMonth || "-"})`, count(faceMonthCount) + "건"],
        [`비대면 상담 데이터 (${overviewMonth || "-"})`, count(remoteMonthCount) + "건"],
      ].map(([label, value]) => `<div class="stat"><div class="label">${label}</div><div class="value">${value}</div></div>`).join("");
    }
    renderOverviewStats();

    // ---------- settlement (월별 정산 보고서) ----------
    // 단가: 센터별 상담사 비용 표(위탁기관ID -> 1급/2급/비대면). 등급: 센터 상담사 등급 표(상담센터ID+상담사ID -> 상담자격).
    // 대면은 상담사 등급에 맞는 1급/2급 단가를, 비대면(전문가)은 항상 비대면 단가를 사용한다.
    const taxStateKey = "eap-settlement-tax-v1";
    let taxState = {};
    try { taxState = JSON.parse(store.getItem(taxStateKey) || "{}") || {}; } catch (e) { taxState = {}; }
    function saveTaxState() { store.setItem(taxStateKey, JSON.stringify(taxState)); }

    // 센터별 정산의 전자계산서/현금영수증 발급 확인 체크 상태
    const docStateKey = "eap-settlement-doc-v1";
    let docState = {};
    try { docState = JSON.parse(store.getItem(docStateKey) || "{}") || {}; } catch (e) { docState = {}; }
    function saveDocState() { store.setItem(docStateKey, JSON.stringify(docState)); }

    // 센터별 정산방식은 전자계산서 · 현금영수증 · 3.3% 중 하나만 선택한다.
    // 기본값은 "선택 없음"이라 아무것도 고르지 않은 센터는 세 칸이 모두 비어 있고,
    // 선택한 칸을 다시 누르면 해제되어 다시 빈 상태로 돌아간다.
    function settleMethod(centerId, docKey) {
      if (taxState[centerTaxKey(centerId)]) return "tax";
      const doc = docState[docKey] || {};
      if (doc.receipt) return "receipt";
      if (doc.invoice) return "invoice";
      return "";
    }
    function setSettleMethod(centerId, docKey, method) {
      taxState[centerTaxKey(centerId)] = method === "tax";
      docState[docKey] = { ...(docState[docKey] || {}), invoice: method === "invoice", receipt: method === "receipt" };
      saveTaxState();
      saveDocState();
    }

    function normId(v) { return String(v || "").trim(); }
    function parseRate(v) {
      if (v === undefined || v === null || String(v).trim() === "") return null;
      const num = Number(String(v).replace(/[^0-9.-]/g, ""));
      return Number.isFinite(num) ? num : null;
    }
    function gradeLookup(counselorId) {
      const rows = gradeGrid.getRows();
      const hit = rows.find(r => normId(r[0]) === normId(counselorId));
      return hit ? String(hit[2] || "").trim() : "";
    }
    function costLookup(orgId) {
      const rows = costGrid.getRows();
      const hit = rows.find(r => normId(r[0]) === normId(orgId));
      if (!hit) return null;
      return { rate1: parseRate(hit[2]), rate2: parseRate(hit[3]), remote: parseRate(hit[4]) };
    }
    // 센터별 상담사 비용 표의 위탁기관ID-위탁기관명 연결을 정산 화면에도 그대로 사용한다.
    function orgNameLookup(orgId, fallback) {
      const rows = costGrid.getRows();
      const hit = rows.find(r => normId(r[0]) === normId(orgId));
      const name = hit ? String(hit[1] || "").trim() : "";
      return name || fallback || "";
    }

    // ---------- 센터 정산서 개별 출력(팝업 인쇄) ----------
    const selectedCenters = new Set();
    const selectedExperts = new Set();
    const selectedTransferRows = new Set();
    function centerBankInfo(centerId) {
      const hit = seed.centers.rows.find(r => normId(r[1]) === normId(centerId)); // 1=상담센터ID
      if (!hit) return { bank: "", account: "", holder: "" };
      return { bank: String(hit[16] || ""), account: String(hit[17] || ""), holder: String(hit[18] || "") }; // 16=은행명, 17=계좌번호, 18=예금주명
    }
    function expertBankInfo(expertId) {
      const hit = seed.experts.rows.find(r => normId(r[2]) === normId(expertId)); // 2=사용아이디(전문가ID)
      if (!hit) return { bank: "", account: "", holder: "" };
      // XLSX_SPECS.experts가 주민번호(원본 17번 열)를 제외하고 불러오므로, 그 뒤 열들은 원본 대비 한 칸씩 앞으로 밀린다.
      // (원본 18=예금주명, 19=입금은행, 20=입금계좌번호 -> 여기서는 17/18/19)
      return { bank: String(hit[18] || ""), account: String(hit[19] || ""), holder: String(hit[17] || "") };
    }
    // 은행명(자유 입력) -> 기업은행 대량이체 양식의 CMS 은행코드. 데이터에 남아있는 흔한 표기를 모두 키로 등록해둔다.
    const BANK_CMS_CODES = {
      "산업은행": 2, "KDB산업은행": 2,
      "기업은행": 3, "IBK기업은행": 3, "기업": 3,
      "국민은행": 4, "KB국민은행": 4, "국민": 4,
      "수협은행": 7, "수협": 7, "수협중앙회": 7,
      "수출입은행": 8, "한국수출입은행": 8,
      "농협은행": 11, "농협": 11, "NH농협은행": 11, "농협중앙회": 11, "NH농협": 11,
      "우리은행": 20, "우리": 20,
      "SC제일은행": 23, "SC은행": 23, "제일은행": 23,
      "한국씨티은행": 27, "씨티은행": 27, "씨티": 27,
      "대구은행": 31, "iM뱅크": 31, "IM뱅크": 31,
      "부산은행": 32,
      "광주은행": 34,
      "제주은행": 35,
      "전북은행": 37,
      "경남은행": 39,
      "새마을금고": 45, "새마을금고중앙회": 45, "MG새마을금고": 45,
      "신협": 48, "신협중앙회": 48,
      "우체국": 71, "우체국예금보험": 71,
      "하나은행": 81, "외환은행": 81, "KEB하나은행": 81, "하나": 81,
      "신한은행": 88, "신한": 88,
      "케이뱅크": 89,
      "카카오뱅크": 90, "카카오": 90,
      "토스뱅크": 92,
      "NH": 11,
      "KB국민": 4,
    };
    const BANK_CMS_LOOKUP = Object.fromEntries(Object.entries(BANK_CMS_CODES).map(([k, v]) => [k.replace(/\s+/g, "").toLowerCase(), v]));
    function bankCmsCode(bankName) {
      const key = String(bankName || "").replace(/\s+/g, "").toLowerCase();
      return BANK_CMS_LOOKUP[key] ?? null;
    }
    function updateBulkPrintButton() {
      const btn = document.getElementById("faceBulkPrint");
      btn.textContent = `선택 출력 (${selectedCenters.size})`;
      btn.disabled = selectedCenters.size === 0;
    }
    function updateRemoteBulkPrintButton() {
      const btn = document.getElementById("remoteBulkPrint");
      btn.textContent = `선택 출력 (${selectedExperts.size})`;
      btn.disabled = selectedExperts.size === 0;
    }
    const SETTLEMENT_SHEET_STYLE = `
      * { box-sizing:border-box; margin:0; padding:0; }
      body { font-family:'Pretendard','Noto Sans KR','Malgun Gothic',sans-serif; background:#fff; }
      .sheet-page { width:720px; margin:0 auto; padding:56px 60px; page-break-after:always; }
      .sheet-page:last-child { page-break-after:auto; }
      @media screen {
        body { background:#e2e5e9; padding:0 0 24px; }
        .sheet-page { background:#fff; box-shadow:0 1px 5px rgba(0,0,0,.3); margin:24px auto; border-radius:1px; }
      }
      .sheet-header { position:relative; margin-bottom:32px; }
      .sheet-month { position:absolute; top:-8px; right:0; font-size:14px; font-weight:500; color:#333; letter-spacing:.04em; }
      .sheet-title { font-size:28px; font-weight:700; letter-spacing:.22em; color:#111; text-align:center; }
      .sheet-rule { border:none; border-top:2px solid #111; }
      .sheet-info { width:100%; border-collapse:collapse; table-layout:fixed; }
      .sheet-info tr { height:44px; }
      .sheet-info td { padding:0 8px; font-size:15px; vertical-align:middle; border-bottom:1px solid #ebebeb; }
      .sheet-info td.lbl { width:76px; font-size:14px; color:#555; font-weight:400; letter-spacing:.04em; }
      .sheet-info td.val { color:#111; font-weight:500; }
      .sheet-items { width:100%; border-collapse:collapse; table-layout:fixed; font-size:15px; margin-top:32px; }
      .sheet-items thead tr { border-top:1.5px solid #111; }
      .sheet-items thead tr.unit-row { border-top:none; }
      .sheet-items .unit-row th { height:auto; padding:0 4px 5px; font-size:12px; font-weight:400; color:#666; letter-spacing:.02em; text-align:right; border-bottom:none; }
      .sheet-items th { height:42px; padding:6px 4px; font-weight:500; font-size:13px; color:#222; letter-spacing:.02em; border-bottom:1px solid #ccc; vertical-align:middle; text-align:center; word-break:keep-all; overflow-wrap:break-word; line-height:1.35; }
      /* 금액·회기 수 칸은 숫자가 중간에 끊기면 안 되므로 줄바꿈을 막는다. */
      .sheet-items td { height:42px; padding:6px 4px; text-align:center; color:#111; border-bottom:1px solid #ebebeb; vertical-align:middle; white-space:nowrap; }
      /* 기관명·상담사명·자격 칸은 띄어쓰기(단어) 단위로 줄바꿈한다. 한 단어가 칸보다 길 때만 그 단어를 쪼갠다. */
      .sheet-items td.txt { white-space:normal; word-break:keep-all; overflow-wrap:break-word; line-height:1.45; }
      .sheet-items .total-row td { height:46px; border-top:1.5px solid #111; border-bottom:1.5px solid #111; font-weight:700; color:#111; }
      .sheet-summary { width:100%; border-collapse:collapse; table-layout:fixed; margin-top:24px; border-top:1px solid #e8e8e8; }
      .sheet-summary tr { height:54px; }
      .sheet-summary td { padding:0 10px; vertical-align:middle; }
      .sheet-summary td.lbl { font-size:14px; color:#555; letter-spacing:.06em; width:110px; white-space:nowrap; }
      .sheet-summary td.amt { text-align:right; font-size:24px; font-weight:700; color:#111; }
      .sheet-summary td.amt em { font-style:normal; font-size:15px; font-weight:400; margin-left:4px; color:#333; }
      .sheet-notice { margin-top:28px; padding-top:16px; border-top:1px solid #ebebeb; font-size:14px; color:#555; line-height:1.9; letter-spacing:.02em; }
      .sheet-notice .notice-title { font-size:13px; font-weight:500; color:#333; letter-spacing:.06em; margin-bottom:4px; }
      .sheet-notice ul { padding-left:0; list-style:none; }
      .sheet-notice ul li::before { content:"—"; margin-right:6px; color:#999; }
      .sheet-notice ul li strong { color:#111; font-weight:500; }
      .sheet-paydate { margin-top:22px; text-align:right; font-size:14px; color:#666; letter-spacing:.04em; }
      .sheet-paydate strong { color:#111; font-weight:500; margin-left:6px; }
      @media print { .sheet-page { padding:24px 40px; margin:0 auto; box-shadow:none; } body { background:#fff; padding:0; } }
    `;
    function invoiceNoticeLines(settlementMonth) {
      const [sy, sm] = settlementMonth.split("-").map(Number);
      const lastDay = new Date(sy, sm, 0).getDate();
      const nextMonth = sm === 12 ? 1 : sm + 1;
      return [
        `전자계산서 발행은 작성일자를 <strong>${sm}월 ${lastDay}일</strong>로 하여 <strong>${nextMonth}월 10일 전까지 발급</strong>해주세요.`,
        `현금영수증 발행 업체는 <strong>현금영수증 발행</strong>해주세요.`,
      ];
    }
    function buildSettlementSheetHtml(centerId, faceRowsFlat, monthLabel, settlementMonth) {
      const rows = faceRowsFlat.filter(r => r.centerId === centerId);
      if (!rows.length) return "";
      const meta = centerBankInfo(centerId);
      const centerName = rows[0].center;
      // 정산방식을 3.3%로 고른 센터는 비대면 정산서처럼 소득세 · 실지급액 칸을 함께 싣고, 그 외에는 예전 그대로 지급금액까지만 싣는다.
      const taxed = !!rows[0].checked;
      const totSessions = sum(rows, r => r.sessions);
      const totPay = sum(rows, r => r.gross || 0);
      const totTax = sum(rows, r => r.tax || 0);
      const totNet = sum(rows, r => r.net || 0);
      // 금액 칸은 숫자만 싣는다. 단위(원)는 표 맨 위 헤더 행에 한 번만 적는다.
      const amt = v => (v != null ? count(v) : "-");
      const rowsHtml = rows.map(r => `<tr><td class="txt">${escapeHtml(r.org)}</td><td class="txt">${escapeHtml(r.counselor)}</td><td class="txt">${escapeHtml(r.grade)}</td><td>${r.unit != null ? count(r.unit) : "미등록"}</td><td>${count(r.sessions)}</td><td>${amt(r.gross)}</td>${taxed ? `<td>${count(r.tax)}</td><td>${amt(r.net)}</td>` : ""}</tr>`).join("");
      return `<div class="sheet-page">
        <div class="sheet-header"><div class="sheet-month">${escapeHtml(monthLabel)}</div><div class="sheet-title">정&nbsp;&nbsp;산&nbsp;&nbsp;서</div></div>
        <hr class="sheet-rule">
        <table class="sheet-info">
          <colgroup><col style="width:72px"><col><col style="width:72px"><col></colgroup>
          <tr><td class="lbl">상담센터</td><td class="val" colspan="3">${escapeHtml(centerName)}</td></tr>
          <tr><td class="lbl">은&nbsp;&nbsp;&nbsp;행</td><td class="val">${escapeHtml(meta.bank)}</td><td class="lbl">계좌번호</td><td class="val">${escapeHtml(meta.account)}</td></tr>
        </table>
        <table class="sheet-items">
          ${taxed
            ? `<colgroup><col style="width:23%"><col style="width:11%"><col style="width:7%"><col style="width:12%"><col style="width:7%"><col style="width:14%"><col style="width:13%"><col style="width:13%"></colgroup>`
            : `<colgroup><col style="width:28%"><col style="width:13%"><col style="width:11%"><col style="width:14%"><col style="width:10%"><col style="width:24%"></colgroup>`}
          <thead><tr class="unit-row"><th colspan="${taxed ? 8 : 6}">(단위: 원)</th></tr>
          <tr><th>위탁기관</th><th>상담사명</th><th>상담 자격</th><th>단가</th><th>회기 수</th><th>지급금액</th>${taxed ? `<th>소득세 (3.3%)</th><th>실지급액</th>` : ""}</tr></thead>
          <tbody>${rowsHtml}</tbody>
          <tfoot><tr class="total-row"><td colspan="4">합&nbsp;&nbsp;계</td><td>${count(totSessions)}</td><td>${count(totPay)}</td>${taxed ? `<td>${count(totTax)}</td><td>${count(totNet)}</td>` : ""}</tr></tfoot>
        </table>
        <table class="sheet-summary"><tr><td class="lbl">${taxed ? "실 지 급 액" : "지 급 금 액"}</td><td class="amt">${count(taxed ? totNet : totPay)}<em>원</em></td></tr></table>
        <div class="sheet-notice">
          <div class="notice-title">입금 안내</div>
          <ul>
            ${(taxed
                ? [`정산 금액은 <strong>${payDateLabel(settlementMonth)}</strong>에 입금됩니다.`]
                : invoiceNoticeLines(settlementMonth)
              ).map(line => `<li>${line}</li>`).join("")}
          </ul>
        </div>
      </div>`;
    }
    function buildPreviewDoc(pagesHtml) {
      return `<!doctype html><html lang="ko"><head><meta charset="utf-8"><title>정산서 미리보기</title><style>${SETTLEMENT_SHEET_STYLE}
        .preview-toolbar { position:sticky; top:0; z-index:10; display:flex; justify-content:center; align-items:center; gap:8px; padding:12px; background:#f5f6f8; border-bottom:1px solid #e2e4e8; }
        .preview-toolbar button { min-height:36px; padding:8px 18px; font-size:14px; font-weight:700; border:1px solid #d8dce2; border-radius:6px; background:#fff; cursor:pointer; }
        .preview-toolbar button.primary { background:#17202d; border-color:#17202d; color:#fff; }
        .preview-toolbar .page-count { font-size:13px; color:#667085; margin-right:8px; }
        @media print { .preview-toolbar { display:none; } }
      </style></head><body><div class="preview-toolbar"><span class="page-count">총 ${pagesHtml.count}장</span><button class="primary" onclick="window.print()">인쇄</button><button onclick="window.close()">닫기</button></div>${pagesHtml.html}</body></html>`;
    }
    function openSettlementSheets(centerIds) {
      if (!settlementMonth) { alert("정산월을 먼저 선택해 주세요."); return; }
      const faceRowsFlat = withTax(buildFaceSettlement(settlementMonth));
      const monthLabel = `${settlementMonth.slice(0, 4)}년 ${Number(settlementMonth.slice(5, 7))}월`;
      const pages = centerIds.map(id => buildSettlementSheetHtml(id, faceRowsFlat, monthLabel, settlementMonth)).filter(Boolean);
      if (!pages.length) { alert("출력할 정산서가 없습니다. 해당 센터의 회기 데이터를 확인해 주세요."); return; }
      const win = window.open("", "_blank");
      if (!win) { alert("팝업이 차단되었습니다. 브라우저의 팝업 차단을 해제한 뒤 다시 시도해 주세요."); return; }
      win.document.write(buildPreviewDoc({ html: pages.join(""), count: pages.length }));
      win.document.close();
      win.focus();
    }

    // ---------- 비대면 정산서(전문가별 출력) ----------
    // 비대면은 소득세 3.3%가 전 건에 적용되므로, 정산서에도 지급금액 · 소득세 · 실지급액을 함께 싣는다.
    function payDateLabel(settlementMonth) {
      const [sy, sm] = settlementMonth.split("-").map(Number);
      const y = sm === 12 ? sy + 1 : sy;
      const m = sm === 12 ? 1 : sm + 1;
      return `${y}년 ${m}월 10일`;
    }
    function buildRemoteSheetHtml(expertId, remoteRowsFlat, monthLabel, settlementMonth) {
      const rows = remoteRowsFlat.filter(r => r.expertId === expertId);
      if (!rows.length) return "";
      const meta = expertBankInfo(expertId);
      const expertName = rows[0].expert;
      const totSessions = sum(rows, r => r.sessions);
      const totGross = sum(rows, r => r.gross || 0);
      const totTax = sum(rows, r => r.tax || 0);
      const totNet = sum(rows, r => r.net || 0);
      const amt = v => (v != null ? count(v) : "-");
      const rowsHtml = rows.map(r => `<tr><td class="txt">${escapeHtml(r.org)}</td><td>${r.unit != null ? count(r.unit) : "미등록"}</td><td>${count(r.sessions)}</td><td>${amt(r.gross)}</td><td>${count(r.tax)}</td><td>${amt(r.net)}</td></tr>`).join("");
      return `<div class="sheet-page">
        <div class="sheet-header"><div class="sheet-month">${escapeHtml(monthLabel)}</div><div class="sheet-title">정&nbsp;&nbsp;산&nbsp;&nbsp;서</div></div>
        <hr class="sheet-rule">
        <table class="sheet-info">
          <colgroup><col style="width:72px"><col><col style="width:72px"><col></colgroup>
          <tr><td class="lbl">상담사</td><td class="val" colspan="3">${escapeHtml(expertName)}</td></tr>
          <tr><td class="lbl">은&nbsp;&nbsp;&nbsp;행</td><td class="val">${escapeHtml(meta.bank)}</td><td class="lbl">계좌번호</td><td class="val">${escapeHtml(meta.account)}</td></tr>
        </table>
        <table class="sheet-items">
          <colgroup><col style="width:30%"><col style="width:14%"><col style="width:10%"><col style="width:16%"><col style="width:14%"><col style="width:16%"></colgroup>
          <thead><tr class="unit-row"><th colspan="6">(단위: 원)</th></tr>
          <tr><th>위탁기관</th><th>상담료</th><th>회기 수</th><th>지급금액</th><th>소득세 (3.3%)</th><th>실지급액</th></tr></thead>
          <tbody>${rowsHtml}</tbody>
          <tfoot><tr class="total-row"><td colspan="2">합&nbsp;&nbsp;계</td><td>${count(totSessions)}</td><td>${count(totGross)}</td><td>${count(totTax)}</td><td>${count(totNet)}</td></tr></tfoot>
        </table>
        <table class="sheet-summary"><tr><td class="lbl">실 지 급 액</td><td class="amt">${count(totNet)}<em>원</em></td></tr></table>
        <div class="sheet-paydate">입금 예정일<strong>${payDateLabel(settlementMonth)}</strong></div>
      </div>`;
    }
    function openRemoteSettlementSheets(expertIds) {
      if (!settlementMonth) { alert("정산월을 먼저 선택해 주세요."); return; }
      const remoteRowsFlat = withTax(buildRemoteSettlement(settlementMonth));
      const monthLabel = `${settlementMonth.slice(0, 4)}년 ${Number(settlementMonth.slice(5, 7))}월`;
      const pages = expertIds.map(id => buildRemoteSheetHtml(id, remoteRowsFlat, monthLabel, settlementMonth)).filter(Boolean);
      if (!pages.length) { alert("출력할 정산서가 없습니다. 해당 전문가의 회기 데이터를 확인해 주세요."); return; }
      const win = window.open("", "_blank");
      if (!win) { alert("팝업이 차단되었습니다. 브라우저의 팝업 차단을 해제한 뒤 다시 시도해 주세요."); return; }
      win.document.write(buildPreviewDoc({ html: pages.join(""), count: pages.length }));
      win.document.close();
      win.focus();
    }

    function buildFaceSettlement(month) {
      const monthCol = seed.faceDataMonthCol;
      const rows = seed.faceData.rows.filter(r => String(r[monthCol] || "").slice(0, 7) === month);
      const groups = groupBy(rows, r => `${r[8]}|${r[7]}|${r[5]}`);
      return groups.map(([key, list]) => {
        const f = list[0];
        const orgId = f[8], org = orgNameLookup(orgId, f[9]), centerId = f[7], center = f[6], counselorId = f[5], counselor = f[4];
        const grade = gradeLookup(counselorId);
        const cost = costLookup(orgId);
        const unit = grade === "1급" ? cost?.rate1 ?? null : grade === "2급" ? cost?.rate2 ?? null : null;
        const sessions = list.length;
        const gross = unit != null ? unit * sessions : null;
        const rowKey = `${month}|face|${orgId}|${centerId}|${counselorId}`;
        return { rowKey, orgId, org, centerId, center, counselorId, counselor, grade, unit, sessions, gross };
      }).sort((a, b) => (a.org || "").localeCompare(b.org || "", "ko") || (a.counselor || "").localeCompare(b.counselor || "", "ko"));
    }

    function buildRemoteSettlement(month) {
      const monthCol = seed.remoteDataMonthCol;
      const rows = seed.remoteData.rows.filter(r => String(r[monthCol] || "").slice(0, 7) === month);
      const groups = groupBy(rows, r => `${r[1]}|${r[12]}`);
      return groups.map(([key, list]) => {
        const f = list[0];
        const orgId = f[1], org = orgNameLookup(orgId, f[2]), expertId = f[12], expert = f[13];
        const cost = costLookup(orgId);
        const unit = cost?.remote ?? null;
        const sessions = list.length;
        const gross = unit != null ? unit * sessions : null;
        const rowKey = `${month}|remote|${orgId}|${expertId}`;
        return { rowKey, orgId, org, expertId, expert, unit, sessions, gross };
      }).sort((a, b) => (a.org || "").localeCompare(b.org || "", "ko") || (a.expert || "").localeCompare(b.expert || "", "ko"));
    }

    function centerTaxKey(centerId) {
      return `${settlementMonth}|face|centertax|${centerId}`;
    }
    function withTax(list) {
      return list.map(r => {
        // 비대면은 항상 3.3% 소득세를 적용(선택 불가)하고, 대면은 센터별 정산방식이 3.3%일 때만 적용한다.
        const isRemote = r.rowKey.split("|")[1] === "remote";
        const checked = isRemote ? true : !!taxState[centerTaxKey(r.centerId)];
        const tax = checked && r.gross != null ? Math.round(r.gross * 0.033) : 0;
        const net = r.gross != null ? r.gross - tax : null;
        return { ...r, checked, tax, net };
      });
    }

    function monthsForSettlement() {
      const a = monthsIn(seed.faceData, seed.faceDataMonthCol);
      const b = monthsIn(seed.remoteData, seed.remoteDataMonthCol);
      return [...new Set([...a, ...b])].sort().reverse();
    }
    // 데이터가 있으면 실제 이번 달을, 없으면 데이터가 있는 가장 최근 달을 "해당 월"로 삼는다.
    function defaultRelevantMonth() {
      const months = monthsForSettlement();
      const now = new Date();
      const currentMonth = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}`;
      if (months.includes(currentMonth)) return currentMonth;
      return months[0] || "";
    }

    let settlementMonth = "";
    function renderStats(faceRows, remoteRows) {
      const all = [...faceRows, ...remoteRows];
      // 대면/비대면 상담 건수는 정산금액과 같은 기준으로 센다 — 단가가 없어 금액에 못 들어간 회기는 빼고,
      // 대신 몇 건이 빠졌는지 아래 작은 글씨로 같이 보여 준다.
      // (바로 아래 "총 상담 건수"는 예전 그대로 미등록까지 포함한 전체 회기 수다.)
      const billedSessions = rows => sum(rows.filter(r => r.gross != null), r => r.sessions);
      const skippedSessions = rows => sum(rows.filter(r => r.gross == null), r => r.sessions);
      const sessionCell = rows => count(billedSessions(rows)) + "건" + excludedNote(skippedSessions(rows));
      document.getElementById("stats").innerHTML = [
        ["대면 정산금액", money(sum(faceRows, r => r.net || 0))],
        ["대면 상담 건수", sessionCell(faceRows)],
        ["비대면 정산금액", money(sum(remoteRows, r => r.net || 0))],
        ["비대면 상담 건수", sessionCell(remoteRows)],
        ["총 상담 건수", count(sum(all, r => r.sessions)) + "건"],
        ["3.3% 세금", money(sum(all, r => r.tax || 0))],
        ["총 실지급액", money(sum(all, r => r.net || 0))],
      ].map(([label, value]) => `<div class="stat"><div class="label">${label}</div><div class="value">${value}</div></div>`).join("");
    }

    function unitCell(unit) {
      return unit != null ? money(unit) : `<span style="color:var(--red);font-weight:800;">미등록</span>`;
    }
    function grossCell(gross) {
      return gross != null ? money(gross) : `<span style="color:var(--red);font-weight:800;">-</span>`;
    }

    // 그룹 합계는 단가 미등록(빈 값) 행을 빼고 계산한다.
    // 회기 수는 실제로 진행된 상담 건수라 미등록 행까지 그대로 세고, 금액만 산출 가능한 행으로 더한다.
    // 그룹 전체가 미등록이면 낼 수 있는 합계가 없으므로 null(-)로 남긴다.
    function sumGroup(list) {
      const priced = list.filter(r => r.gross != null);
      return {
        sessions: sum(list, r => r.sessions),
        gross: priced.length ? sum(priced, r => r.gross) : null,
        tax: sum(priced, r => r.tax),
        net: priced.length ? sum(priced, r => r.net) : null,
        missingCount: list.length - priced.length,
      };
    }
    function excludedNote(n) {
      return n ? `<span class="excluded-note">미등록 ${count(n)}건 제외</span>` : "";
    }

    // 상담사/전문가별 상세 행을 센터/기관 단위로 합산한다.
    function aggregateRows(rows, keyFn, buildLabel) {
      return groupBy(rows, keyFn).map(([key, list]) => ({
        ...buildLabel(list[0], list),
        ...sumGroup(list),
      })).sort((a, b) => (a.center || "").localeCompare(b.center || "", "ko") || (a.org || "").localeCompare(b.org || "", "ko"));
    }

    let faceGroupView = "center";
    const expandedCenters = new Set();
    const expandedOrgs = new Set();
    const expandedRemoteOrgs = new Set();
    function renderFaceSettle(faceRows) {
      const q = document.getElementById("faceSettleSearch").value.trim();
      const filtered = faceRows.filter(r => textMatch(r, q));
      const table = document.getElementById("faceSettleTable");

      if (faceGroupView === "center") {
        // 센터가 여러 위탁기관과 거래하더라도 상담센터ID 기준으로 한 센터당 한 행만 나오게 합산하고,
        // 행을 누르면 그 센터의 위탁기관별 내역이 아래로 펼쳐진다.
        const rows = groupBy(filtered, r => r.centerId).map(([centerId, list]) => {
          const f = list[0];
          return {
            centerId, center: f.center,
            org: [...new Set(list.map(r => r.org))].filter(Boolean).join(", "),
            ...sumGroup(list),
            docKey: `${settlementMonth}|face|center|${centerId}`,
            orgBreakdown: aggregateRows(list, r => r.orgId, of => ({ orgId: of.orgId, org: of.org })),
          };
        }).sort((a, b) => (a.center || "").localeCompare(b.center || "", "ko"));

        table.innerHTML =
          `<thead><tr><th class="select-col"><input type="checkbox" id="faceSelectAll" title="전체 선택" class="select-check" /></th><th style="width:22px;"></th><th>순번</th><th>상담센터ID</th><th>상담센터명</th><th>위탁기관</th><th class="num">회기</th><th class="num">지급금액</th><th class="num">소득세(3.3%)</th><th class="num">실지급액</th><th class="doc-col" style="text-align:center;">전자계산서</th><th class="doc-col" style="text-align:center;">현금영수증</th><th class="doc-col" style="text-align:center;">3.3%</th><th class="print-col" style="width:70px;">출력</th></tr></thead>` +
          (rows.length
            ? `<tbody>${rows.map((r, i) => {
                const method = settleMethod(r.centerId, r.docKey);
                const methodCell = m => `<td class="doc-col" data-noexpand="1"><input type="checkbox" class="method-check" data-center="${escapeHtml(r.centerId)}" data-key="${escapeHtml(r.docKey)}" data-method="${m}" ${method === m ? "checked" : ""} /></td>`;
                const expanded = expandedCenters.has(r.centerId);
                const selected = selectedCenters.has(r.centerId);
                const mainRow = `<tr class="center-row" data-center="${escapeHtml(r.centerId)}"><td class="select-col" data-noexpand="1"><input type="checkbox" class="select-check" data-center="${escapeHtml(r.centerId)}" ${selected ? "checked" : ""} /></td><td class="expand-toggle">${expanded ? "▾" : "▸"}</td><td>${i + 1}</td><td>${escapeHtml(r.centerId)}</td><td>${escapeHtml(r.center)}</td><td>${escapeHtml(r.org)}</td><td class="num">${count(r.sessions)}</td><td class="num">${grossCell(r.gross)}${excludedNote(r.missingCount)}</td><td class="num">${r.tax ? money(r.tax) : ""}</td><td class="num"><strong>${grossCell(r.net)}</strong></td>${methodCell("invoice")}${methodCell("receipt")}${methodCell("tax")}<td class="print-col" data-noexpand="1"><button class="btn-print-one ghost" data-center="${escapeHtml(r.centerId)}">출력</button></td></tr>`;
                // 하위 행도 같은 표의 컬럼을 그대로 써서 회기/지급금액/소득세/실지급액 칸이 원래 표와 정확히 맞도록 한다.
                const detailRows = expanded ? r.orgBreakdown.map(o => `<tr class="org-detail-row"><td></td><td></td><td></td><td></td><td class="org-detail-label">└ ${escapeHtml(o.orgId)}</td><td>${escapeHtml(o.org)}</td><td class="num">${count(o.sessions)}</td><td class="num">${grossCell(o.gross)}${excludedNote(o.missingCount)}</td><td class="num">${o.tax ? money(o.tax) : ""}</td><td class="num">${grossCell(o.net)}</td><td></td><td></td><td></td><td></td></tr>`).join("") : "";
                return mainRow + detailRows;
              }).join("")}</tbody>`
            : emptyRow(14));
        document.querySelectorAll("#faceSettleTable .center-row").forEach(el => el.addEventListener("click", e => {
          if (e.target.closest("[data-noexpand]")) return;
          const centerId = el.dataset.center;
          if (expandedCenters.has(centerId)) expandedCenters.delete(centerId); else expandedCenters.add(centerId);
          renderFaceSettle(faceRows);
        }));
        document.querySelectorAll("#faceSettleTable .method-check").forEach(el => el.addEventListener("change", e => {
          const box = e.target;
          // 체크하면 그 항목만 남기고, 체크를 풀면 셋 다 빈 상태로 되돌린다.
          setSettleMethod(box.dataset.center, box.dataset.key, box.checked ? box.dataset.method : "");
          // 3.3% 여부가 소득세·실지급액·이체파일까지 바꾸므로 정산 화면 전체를 다시 그린다.
          renderSettlementAll();
        }));
        // 체크박스가 작아 정확히 누르기 번거로우니, 칸 아무 데나 눌러도 토글되게 한다(선택 칸과 같은 방식).
        document.querySelectorAll("#faceSettleTable td.doc-col").forEach(cell => cell.addEventListener("click", e => {
          if (e.target.closest("input")) return;
          const input = cell.querySelector(".method-check");
          if (!input) return;
          input.checked = !input.checked;
          input.dispatchEvent(new Event("change", { bubbles: true }));
        }));
        document.querySelectorAll("#faceSettleTable .btn-print-one").forEach(el => el.addEventListener("click", e => {
          e.stopPropagation();
          openSettlementSheets([e.target.dataset.center]);
        }));
        document.querySelectorAll("#faceSettleTable td.select-col, #faceSettleTable th.select-col").forEach(cell => cell.addEventListener("click", e => {
          if (e.target.closest("input")) return;
          const input = cell.querySelector(".select-check");
          if (!input) return;
          input.checked = !input.checked;
          input.dispatchEvent(new Event("change", { bubbles: true }));
        }));
        document.querySelectorAll("#faceSettleTable .select-check[data-center]").forEach(el => el.addEventListener("change", e => {
          const id = e.target.dataset.center;
          if (e.target.checked) selectedCenters.add(id); else selectedCenters.delete(id);
          updateBulkPrintButton();
          const selectAllEl = document.getElementById("faceSelectAll");
          if (selectAllEl) selectAllEl.checked = rows.length > 0 && rows.every(r => selectedCenters.has(r.centerId));
        }));
        const selectAllEl = document.getElementById("faceSelectAll");
        if (selectAllEl) {
          selectAllEl.checked = rows.length > 0 && rows.every(r => selectedCenters.has(r.centerId));
          selectAllEl.addEventListener("change", e => {
            if (e.target.checked) rows.forEach(r => selectedCenters.add(r.centerId));
            else rows.forEach(r => selectedCenters.delete(r.centerId));
            updateBulkPrintButton();
            renderFaceSettle(faceRows);
          });
        }
        updateBulkPrintButton();
        return;
      }

      if (faceGroupView === "counselor") {
        table.innerHTML =
          `<thead><tr><th>순번</th><th>상담센터ID</th><th>상담센터명</th><th>위탁기관</th><th>상담사ID</th><th>상담사명</th><th>등급</th><th class="num">단가</th><th class="num">회기</th><th class="num">지급금액</th><th class="num">소득세(3.3%)</th><th class="num">실지급액</th></tr></thead>` +
          (filtered.length
            ? `<tbody>${filtered.map((r, i) => `<tr><td>${i + 1}</td><td>${escapeHtml(r.centerId)}</td><td>${escapeHtml(r.center)}</td><td>${escapeHtml(r.org)}</td><td>${escapeHtml(r.counselorId)}</td><td>${escapeHtml(r.counselor)}</td><td>${escapeHtml(r.grade)}</td><td class="num">${unitCell(r.unit)}</td><td class="num">${count(r.sessions)}</td><td class="num">${grossCell(r.gross)}</td><td class="num">${r.tax ? money(r.tax) : ""}</td><td class="num"><strong>${grossCell(r.net)}</strong></td></tr>`).join("")}</tbody>`
            : emptyRow(12));
        return;
      }

      // 기관 행을 누르면 그 기관 소속 센터별 내역이 아래로 펼쳐진다.
      const rows = groupBy(filtered, r => r.orgId).map(([orgId, list]) => {
        const f = list[0];
        return {
          orgId, org: f.org,
          ...sumGroup(list),
          centerBreakdown: aggregateRows(list, r => r.centerId, cf => ({ centerId: cf.centerId, center: cf.center })),
        };
      }).sort((a, b) => (a.org || "").localeCompare(b.org || "", "ko"));

      table.innerHTML =
        `<thead><tr><th style="width:22px;"></th><th>순번</th><th>위탁기관ID</th><th>위탁기관</th><th class="num">회기</th><th class="num">지급금액</th><th class="num">소득세(3.3%)</th><th class="num">실지급액</th></tr></thead>` +
        (rows.length
          ? `<tbody>${rows.map((r, i) => {
              const expanded = expandedOrgs.has(r.orgId);
              const mainRow = `<tr class="org-row" data-org="${escapeHtml(r.orgId)}"><td class="expand-toggle">${expanded ? "▾" : "▸"}</td><td>${i + 1}</td><td>${escapeHtml(r.orgId)}</td><td>${escapeHtml(r.org)}</td><td class="num">${count(r.sessions)}</td><td class="num">${grossCell(r.gross)}${excludedNote(r.missingCount)}</td><td class="num">${r.tax ? money(r.tax) : ""}</td><td class="num"><strong>${grossCell(r.net)}</strong></td></tr>`;
              const detailRows = expanded ? r.centerBreakdown.map(c => `<tr class="org-detail-row"><td></td><td></td><td></td><td class="org-detail-label">└ ${escapeHtml(c.centerId)} · ${escapeHtml(c.center)}</td><td class="num">${count(c.sessions)}</td><td class="num">${grossCell(c.gross)}${excludedNote(c.missingCount)}</td><td class="num">${c.tax ? money(c.tax) : ""}</td><td class="num">${grossCell(c.net)}</td></tr>`).join("") : "";
              return mainRow + detailRows;
            }).join("")}</tbody>`
          : emptyRow(8));
      document.querySelectorAll("#faceSettleTable .org-row").forEach(el => el.addEventListener("click", () => {
        const orgId = el.dataset.org;
        if (expandedOrgs.has(orgId)) expandedOrgs.delete(orgId); else expandedOrgs.add(orgId);
        renderFaceSettle(faceRows);
      }));
    }

    let remoteGroupView = "expert";
    function renderRemoteSettle(remoteRows) {
      const q = document.getElementById("remoteSettleSearch").value.trim();
      const filtered = remoteRows.filter(r => textMatch(r, q));
      const table = document.getElementById("remoteSettleTable");

      if (remoteGroupView === "expert") {
        // 정산서는 전문가 단위로 뽑으므로, 한 전문가가 여러 기관에 걸쳐 있어도 체크는 전문가ID 하나로 묶인다.
        const expertIds = [...new Set(filtered.map(r => r.expertId))];
        table.innerHTML =
          `<thead><tr><th class="select-col"><input type="checkbox" id="remoteSelectAll" title="전체 선택" class="select-check" /></th><th>순번</th><th>위탁기관ID</th><th>위탁기관</th><th>전문가ID</th><th>전문가명</th><th class="num">금액</th><th class="num">회기</th><th class="num">지급금액</th><th class="num">소득세(3.3%)</th><th class="num">실지급액</th><th class="print-col" style="width:70px;">출력</th></tr></thead>` +
          (filtered.length
            ? `<tbody>${filtered.map((r, i) => `<tr><td class="select-col"><input type="checkbox" class="select-check" data-expert="${escapeHtml(r.expertId)}" ${selectedExperts.has(r.expertId) ? "checked" : ""} /></td><td>${i + 1}</td><td>${escapeHtml(r.orgId)}</td><td>${escapeHtml(r.org)}</td><td>${escapeHtml(r.expertId)}</td><td>${escapeHtml(r.expert)}</td><td class="num">${unitCell(r.unit)}</td><td class="num">${count(r.sessions)}</td><td class="num">${grossCell(r.gross)}</td><td class="num">${r.tax ? money(r.tax) : ""}</td><td class="num"><strong>${grossCell(r.net)}</strong></td><td class="print-col"><button class="btn-print-one ghost" data-expert="${escapeHtml(r.expertId)}">출력</button></td></tr>`).join("")}</tbody>`
            : emptyRow(12));
        document.querySelectorAll("#remoteSettleTable .btn-print-one").forEach(el => el.addEventListener("click", e => {
          e.stopPropagation();
          openRemoteSettlementSheets([e.target.dataset.expert]);
        }));
        document.querySelectorAll("#remoteSettleTable td.select-col, #remoteSettleTable th.select-col").forEach(cell => cell.addEventListener("click", e => {
          if (e.target.closest("input")) return;
          const input = cell.querySelector(".select-check");
          if (!input) return;
          input.checked = !input.checked;
          input.dispatchEvent(new Event("change", { bubbles: true }));
        }));
        document.querySelectorAll("#remoteSettleTable .select-check[data-expert]").forEach(el => el.addEventListener("change", e => {
          const id = e.target.dataset.expert;
          if (e.target.checked) selectedExperts.add(id); else selectedExperts.delete(id);
          updateRemoteBulkPrintButton();
          // 같은 전문가가 여러 줄에 나뉘어 있으면 나머지 줄의 체크 표시도 함께 맞춘다.
          renderRemoteSettle(remoteRows);
        }));
        const remoteSelectAllEl = document.getElementById("remoteSelectAll");
        if (remoteSelectAllEl) {
          remoteSelectAllEl.checked = expertIds.length > 0 && expertIds.every(id => selectedExperts.has(id));
          remoteSelectAllEl.addEventListener("change", e => {
            if (e.target.checked) expertIds.forEach(id => selectedExperts.add(id));
            else expertIds.forEach(id => selectedExperts.delete(id));
            updateRemoteBulkPrintButton();
            renderRemoteSettle(remoteRows);
          });
        }
        updateRemoteBulkPrintButton();
        return;
      }

      // 기관 행을 누르면 그 기관 소속 전문가별 내역이 아래로 펼쳐진다.
      const rows = groupBy(filtered, r => r.orgId).map(([orgId, list]) => {
        const f = list[0];
        return {
          orgId, org: f.org,
          ...sumGroup(list),
          expertBreakdown: aggregateRows(list, r => r.expertId, ef => ({ expertId: ef.expertId, expert: ef.expert })),
        };
      }).sort((a, b) => (a.org || "").localeCompare(b.org || "", "ko"));

      table.innerHTML =
        `<thead><tr><th style="width:22px;"></th><th>순번</th><th>위탁기관ID</th><th>위탁기관</th><th class="num">회기</th><th class="num">지급금액</th><th class="num">소득세(3.3%)</th><th class="num">실지급액</th></tr></thead>` +
        (rows.length
          ? `<tbody>${rows.map((r, i) => {
              const expanded = expandedRemoteOrgs.has(r.orgId);
              const mainRow = `<tr class="org-row" data-org="${escapeHtml(r.orgId)}"><td class="expand-toggle">${expanded ? "▾" : "▸"}</td><td>${i + 1}</td><td>${escapeHtml(r.orgId)}</td><td>${escapeHtml(r.org)}</td><td class="num">${count(r.sessions)}</td><td class="num">${grossCell(r.gross)}${excludedNote(r.missingCount)}</td><td class="num">${r.tax ? money(r.tax) : ""}</td><td class="num"><strong>${grossCell(r.net)}</strong></td></tr>`;
              const detailRows = expanded ? r.expertBreakdown.map(e => `<tr class="org-detail-row"><td></td><td></td><td></td><td class="org-detail-label">└ ${escapeHtml(e.expertId)} · ${escapeHtml(e.expert)}</td><td class="num">${count(e.sessions)}</td><td class="num">${grossCell(e.gross)}${excludedNote(e.missingCount)}</td><td class="num">${e.tax ? money(e.tax) : ""}</td><td class="num">${grossCell(e.net)}</td></tr>`).join("") : "";
              return mainRow + detailRows;
            }).join("")}</tbody>`
          : emptyRow(8));
      document.querySelectorAll("#remoteSettleTable .org-row").forEach(el => el.addEventListener("click", () => {
        const orgId = el.dataset.org;
        if (expandedRemoteOrgs.has(orgId)) expandedRemoteOrgs.delete(orgId); else expandedRemoteOrgs.add(orgId);
        renderRemoteSettle(remoteRows);
      }));
    }

    // ---------- 은행 이체파일(기업은행 대량이체 양식) ----------
    function buildTransferRows(month) {
      if (!month) return { rows: [], skippedNoPrice: 0 };
      const faceRows = withTax(buildFaceSettlement(month));
      const remoteRows = withTax(buildRemoteSettlement(month));
      const rows = [];
      let skippedNoPrice = 0;
      groupBy(faceRows, r => r.centerId).forEach(([centerId, list]) => {
        if (list.some(r => r.gross == null)) { skippedNoPrice++; return; }
        const net = sum(list, r => r.net);
        if (!(net > 0)) return;
        const meta = centerBankInfo(centerId);
        rows.push({
          id: `face|${centerId}`,
          type: "face", name: list[0].center,
          bank: meta.bank, account: meta.account,
          printName: meta.holder || list[0].center,
          amount: net,
          hasBank: !!(meta.bank && meta.account),
        });
      });
      groupBy(remoteRows, r => r.expertId).forEach(([expertId, list]) => {
        if (list.some(r => r.gross == null)) { skippedNoPrice++; return; }
        const net = sum(list, r => r.net);
        if (!(net > 0)) return;
        const meta = expertBankInfo(expertId);
        rows.push({
          id: `remote|${expertId}`,
          type: "remote", name: list[0].expert,
          bank: meta.bank, account: meta.account,
          printName: meta.holder || list[0].expert,
          amount: net,
          hasBank: !!(meta.bank && meta.account),
        });
      });
      rows.sort((a, b) => (a.name || "").localeCompare(b.name || "", "ko"));
      return { rows, skippedNoPrice };
    }
    function transferRow(r) {
      // 계좌번호·CMS코드는 앞자리 0이 사라지지 않도록 문자열로 기록한다.
      return [r.bank, String(r.account ?? ""), Number(r.amount || 0), r.printName, "마이카운슬러", String(bankCmsCode(r.bank) ?? "")];
    }
    const TRANSFER_HEADERS = ["입금은행", "입금계좌번호", "이체금액", "내통장인쇄내용", "받는분통장인쇄내용", "CMS코드"];
    function downloadTransferXlsx(rows, filename) {
      if (!rows.length) { alert("다운로드할 이체 대상이 없습니다."); return; }
      downloadXlsx(filename, TRANSFER_HEADERS, rows.map(transferRow), "대량이체");
    }
    function renderTransferTable() {
      const table = document.getElementById("transferTable");
      const { rows, skippedNoPrice } = buildTransferRows(settlementMonth);
      const ready = rows.filter(r => r.hasBank);
      const missing = rows.filter(r => !r.hasBank);
      const monthLabel = settlementMonth ? settlementMonth.slice(5, 7) + "월" : "";
      const validIds = new Set(rows.map(r => r.id));
      [...selectedTransferRows].forEach(id => { if (!validIds.has(id)) selectedTransferRows.delete(id); });
      table.innerHTML =
        `<thead><tr><th class="select-col"><input type="checkbox" id="transferSelectAll" title="전체 선택" class="select-check" /></th><th>구분</th><th>대상</th><th>입금은행</th><th>계좌번호</th><th class="num">이체금액</th><th>예금주명</th><th>받는분통장인쇄내용</th><th>CMS코드</th><th class="print-col" style="width:90px;">다운로드</th></tr></thead>` +
        (rows.length
          ? `<tbody>${rows.map((r, i) => {
              const cms = bankCmsCode(r.bank);
              const warn = r.hasBank ? "" : ` style="color:var(--red);"`;
              const dl = r.hasBank ? `<button class="btn-print-one ghost transfer-dl-row" data-idx="${i}">다운로드</button>` : "";
              const checked = selectedTransferRows.has(r.id) ? "checked" : "";
              return `<tr${warn}><td class="select-col" data-noexpand="1"><input type="checkbox" class="select-check transfer-select" data-id="${escapeHtml(r.id)}" ${checked} /></td><td>${r.type === "face" ? "대면" : "비대면"}</td><td>${escapeHtml(r.name)}</td><td>${r.hasBank ? escapeHtml(r.bank) : "계좌 미등록"}</td><td>${escapeHtml(r.account)}</td><td class="num">${money(r.amount)}</td><td>${escapeHtml(r.printName)}</td><td>마이카운슬러</td><td>${cms ?? (r.hasBank ? "코드없음" : "")}</td><td class="print-col">${dl}</td></tr>`;
            }).join("")}</tbody>`
          : emptyRow(10));
      const parts = [`총 ${count(rows.length)}건 · ${money(sum(ready, r => r.amount))}`];
      if (missing.length) parts.push(`계좌 미등록 ${missing.length}건 (엑셀 제외)`);
      if (skippedNoPrice) parts.push(`단가 미등록 ${skippedNoPrice}건 제외`);
      document.getElementById("transferSummary").textContent = parts.join(" · ");
      document.querySelectorAll(".transfer-dl-row").forEach(btn => btn.addEventListener("click", () => {
        const r = rows[Number(btn.dataset.idx)];
        downloadTransferXlsx([r], `이체_${r.name}(${monthLabel}귀속).xlsx`);
      }));
      document.getElementById("transferExport").onclick = () => downloadTransferXlsx(ready, `기업은행대량이체용(${monthLabel}귀속).xlsx`);

      function updateSelectedDownloadBtn() {
        const btn = document.getElementById("transferSelectedExport");
        btn.textContent = `선택 다운로드 (${selectedTransferRows.size})`;
        btn.disabled = selectedTransferRows.size === 0;
      }
      function syncSelectAll() {
        const allEl = document.getElementById("transferSelectAll");
        if (allEl) allEl.checked = rows.length > 0 && rows.every(r => selectedTransferRows.has(r.id));
      }
      document.querySelectorAll("#transferTable td.select-col, #transferTable th.select-col").forEach(cell => cell.addEventListener("click", e => {
        if (e.target.closest("input")) return;
        const input = cell.querySelector(".select-check");
        if (!input) return;
        input.checked = !input.checked;
        input.dispatchEvent(new Event("change", { bubbles: true }));
      }));
      document.querySelectorAll(".transfer-select").forEach(el => el.addEventListener("change", e => {
        const id = e.target.dataset.id;
        if (e.target.checked) selectedTransferRows.add(id); else selectedTransferRows.delete(id);
        updateSelectedDownloadBtn();
        syncSelectAll();
      }));
      const selectAllEl = document.getElementById("transferSelectAll");
      syncSelectAll();
      selectAllEl.addEventListener("change", e => {
        if (e.target.checked) rows.forEach(r => selectedTransferRows.add(r.id));
        else rows.forEach(r => selectedTransferRows.delete(r.id));
        renderTransferTable();
      });
      updateSelectedDownloadBtn();
      document.getElementById("transferSelectedExport").onclick = () => {
        const selected = rows.filter(r => selectedTransferRows.has(r.id) && r.hasBank);
        downloadTransferXlsx(selected, `이체_선택(${monthLabel}귀속).xlsx`);
      };
    }

    function renderSettlementAll() {
      const faceRows = withTax(buildFaceSettlement(settlementMonth));
      const remoteRows = withTax(buildRemoteSettlement(settlementMonth));
      renderStats(faceRows, remoteRows);
      renderFaceSettle(faceRows);
      renderRemoteSettle(remoteRows);
      renderTransferTable();
    }

    const settlementMonthSel = document.getElementById("settlementMonth");
    function refreshSettlementMonths() {
      const settlementMonths = monthsForSettlement();
      settlementMonthSel.innerHTML = settlementMonths.map(m => `<option value="${m}">${m}</option>`).join("");
      // 데이터가 있으면 실제 이번 달을 기본값으로 열고, 없으면 데이터가 있는 가장 최근 달로 대체한다.
      const now = new Date();
      const currentMonth = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}`;
      if (settlementMonths.includes(currentMonth)) settlementMonth = currentMonth;
      else if (settlementMonths.includes(settlementMonth)) { /* keep current selection */ }
      else if (settlementMonths.length) settlementMonth = settlementMonths[0];
      else settlementMonth = "";
      settlementMonthSel.value = settlementMonth;
    }
    refreshSettlementMonths();
    settlementMonthSel.addEventListener("change", () => {
      settlementMonth = settlementMonthSel.value;
      selectedCenters.clear();
      selectedExperts.clear();
      updateBulkPrintButton();
      updateRemoteBulkPrintButton();
      renderSettlementAll();
    });
    document.getElementById("faceBulkPrint").addEventListener("click", () => {
      if (!selectedCenters.size) return;
      openSettlementSheets([...selectedCenters]);
    });
    document.getElementById("remoteBulkPrint").addEventListener("click", () => {
      if (!selectedExperts.size) return;
      openRemoteSettlementSheets([...selectedExperts]);
    });

    document.querySelectorAll(".tab").forEach(tab => tab.addEventListener("click", () => {
      document.querySelectorAll(".tab").forEach(t => t.classList.toggle("active", t === tab));
      const view = tab.dataset.view;
      ["face", "remote", "transfer"].forEach(v => document.getElementById("view-" + v).classList.toggle("hidden", v !== view));
    }));
    ["faceSettleSearch", "remoteSettleSearch"].forEach(id => document.getElementById(id).addEventListener("input", renderSettlementAll));

    document.querySelectorAll('.subtabs[data-scope="facegroup"] .subtab').forEach(btn => btn.addEventListener("click", () => {
      document.querySelectorAll('.subtabs[data-scope="facegroup"] .subtab').forEach(b => b.classList.toggle("active", b === btn));
      faceGroupView = btn.dataset.facegroup;
      renderSettlementAll();
    }));
    document.querySelectorAll('.subtabs[data-scope="remotegroup"] .subtab').forEach(btn => btn.addEventListener("click", () => {
      document.querySelectorAll('.subtabs[data-scope="remotegroup"] .subtab').forEach(b => b.classList.toggle("active", b === btn));
      remoteGroupView = btn.dataset.remotegroup;
      renderSettlementAll();
    }));

    // ---------- xlsx upload wiring ----------
    function wireUpload(inputId, statusId, handler) {
      document.getElementById(inputId).addEventListener("change", async e => {
        const file = e.target.files[0];
        if (!file) return;
        const status = document.getElementById(statusId);
        status.textContent = "불러오는 중...";
        try {
          const wb = await xlsxReadWorkbook(file);
          await handler(wb);
          const now = new Date();
          status.textContent = `${file.name} 반영됨 (${String(now.getHours()).padStart(2, "0")}:${String(now.getMinutes()).padStart(2, "0")})`;
        } catch (err) {
          status.textContent = "파일을 읽지 못했습니다: " + (err && err.message ? err.message : err);
        }
        e.target.value = "";
      });
    }

    wireUpload("centerUpload", "centerUploadStatus", wb => {
      const board = xlsxSheetToBoard(wb.Sheets[wb.SheetNames[0]], XLSX_SPECS.centers);
      seed.centers = board;
      saveUploadOverride("centers", board);
      centerBoard.setData(board);
      renderOverviewStats();
    });
    wireUpload("counselorUpload", "counselorUploadStatus", wb => {
      const board = xlsxSheetToBoard(wb.Sheets[wb.SheetNames[0]], XLSX_SPECS.counselors);
      seed.counselors = board;
      saveUploadOverride("counselors", board);
      counselorBoard.setData(board);
      renderOverviewStats();
    });
    wireUpload("expertUpload", "expertUploadStatus", wb => {
      const board = xlsxSheetToBoard(wb.Sheets[wb.SheetNames[0]], XLSX_SPECS.experts);
      seed.experts = board;
      saveUploadOverride("experts", board);
      expertBoard.setData(board);
      renderOverviewStats();
    });
    wireUpload("recordsUpload", "recordsUploadStatus", wb => {
      const faceWs = wb.Sheets[XLSX_SPECS.faceData.sheetName];
      const remoteWs = wb.Sheets[XLSX_SPECS.remoteData.sheetName];
      if (!faceWs && !remoteWs) throw new Error(`시트를 찾을 수 없습니다 (${XLSX_SPECS.faceData.sheetName} / ${XLSX_SPECS.remoteData.sheetName})`);
      if (faceWs) {
        const board = xlsxSheetToBoard(faceWs, XLSX_SPECS.faceData);
        seed.faceData = board;
        saveUploadOverride("faceData", board);
        faceBoard.setData(board);
      }
      if (remoteWs) {
        const board = xlsxSheetToBoard(remoteWs, XLSX_SPECS.remoteData);
        seed.remoteData = board;
        saveUploadOverride("remoteData", board);
        remoteBoard.setData(board);
      }
      renderOverviewStats();
      refreshSettlementMonths();
      renderSettlementAll();
    });
    wireUpload("gradeUpload", "gradeUploadStatus", wb => {
      const board = xlsxSheetToBoard(wb.Sheets[wb.SheetNames[0]], XLSX_SPECS.grade);
      gradeGrid.setRows(board.rows);
      renderSettlementAll();
    });
    wireUpload("costUpload", "costUploadStatus", wb => {
      const board = xlsxSheetToBoard(wb.Sheets[wb.SheetNames[0]], XLSX_SPECS.cost);
      costGrid.setRows(board.rows);
      renderSettlementAll();
    });

    renderSettlementAll();
  </script>
</body>
</html>
